Real GridSource::getValue(const Vector3 &position) const
{
    Vector3 scaledPosition(position.x * mPosXScale, position.y * mPosYScale, position.z * mPosZScale);
    Real value;
    if (mTrilinearValue)
    {
        auto x0 = static_cast<size_t>(scaledPosition.x);
        auto x1 = static_cast<size_t>(ceil(scaledPosition.x));
        auto y0 = static_cast<size_t>(scaledPosition.y);
        auto y1 = static_cast<size_t>(ceil(scaledPosition.y));
        auto z0 = static_cast<size_t>(scaledPosition.z);
        auto z1 = static_cast<size_t>(ceil(scaledPosition.z));

        Real dX = scaledPosition.x - static_cast<Real>(x0);
        Real dY = scaledPosition.y - static_cast<Real>(y0);
        Real dZ = scaledPosition.z - static_cast<Real>(z0);

        Real f000 = getVolumeGridValue(x0, y0, z0);
        Real f100 = getVolumeGridValue(x1, y0, z0);
        Real f010 = getVolumeGridValue(x0, y1, z0);
        Real f001 = getVolumeGridValue(x0, y0, z1);
        Real f101 = getVolumeGridValue(x1, y0, z1);
        Real f011 = getVolumeGridValue(x0, y1, z1);
        Real f110 = getVolumeGridValue(x1, y1, z0);
        Real f111 = getVolumeGridValue(x1, y1, z1);

        Real oneMinX = static_cast<Real>(1.0) - dX;
        Real oneMinY = static_cast<Real>(1.0) - dY;
        Real oneMinZ = static_cast<Real>(1.0) - dZ;
        Real oneMinXoneMinY = oneMinX * oneMinY;
        Real dXOneMinY = dX * oneMinY;

        value = (oneMinZ * ((f000 * oneMinXoneMinY)
            + (f100 * dXOneMinY)
            + (f010 * oneMinX * dY)))
            + (dZ * ((f001 * oneMinXoneMinY)
            + (f101 * dXOneMinY)
            + (f011 * oneMinX * dY)))
            + (dX * dY * ((f110 * oneMinZ)
            + (f111 * dZ)));

    }
    else
    {
        // Nearest neighbour else
        auto x = static_cast<size_t>(scaledPosition.x + static_cast<Real>(0.5));
        auto y = static_cast<size_t>(scaledPosition.y + static_cast<Real>(0.5));
        auto z = static_cast<size_t>(scaledPosition.z + static_cast<Real>(0.5));
        value = static_cast<Real>(getVolumeGridValue(x, y, z));
    }
    return value;
}

