std::vector<std::pair<const char*, const char*>> HighLevelGpuProgram::parseDefines(String& defines)
{
    std::vector<std::pair<const char*, const char*>> ret;
    if (defines.empty()) {
        return ret;
}

    String::size_type pos = 0;
    while (pos != String::npos)
    {
        // Find delims
        String::size_type endPos = defines.find_first_of(";,=", pos);
        if (endPos != String::npos)
        {
            String::size_type macro_name_start = pos;
            pos = endPos;

            // Check definition part
            if (defines[pos] == '=')
            {
                // Setup null character for macro name
                defines[pos] = '\0';
                // set up a definition, skip delim
                ++pos;
                String::size_type macro_val_start = pos;

                endPos = defines.find_first_of(";,", pos);
                if (endPos == String::npos)
                {
                    pos = endPos;
                }
                else
                {
                    defines[endPos] = '\0';
                    pos = endPos+1;
                }

                ret.emplace_back(&defines[macro_name_start], &defines[macro_val_start]);
            }
            else
            {
                // Setup null character for macro name
                defines[pos] = '\0';
                // No definition part, define as "1"
                ++pos;

                if(defines[macro_name_start] != '\0') { // e.g ",DEFINE" or "DEFINE,"
                    ret.emplace_back(&defines[macro_name_start], "1");
}
            }
        }
        else
        {
            if(pos < defines.size()) {
                ret.emplace_back(&defines[pos], "1");
}

            pos = endPos;
        }
    }

    return ret;
}

int CRectangleOverlapHandler::HandleOverlapping(SRectangle* rect1, SRectangle* rect2)
{
	//  ______
	// |      |  ___
	// |      | |   |
	// |      | |___|
	// |______|
	//
	if (!rect1->CheckOverlap(*rect2)) {
		return 0;
}

	// make rect1 point to the `larger`/`outer` rectangle
	bool swapped = false;
	std::bitset<4> edgesInRect12 = GetEdgesInRect(*rect1, *rect2);
	std::bitset<4> edgesInRect21 = GetEdgesInRect(*rect2, *rect1);
	if (edgesInRect12.count() < edgesInRect21.count()) {
		std::swap(edgesInRect12, edgesInRect21);
		std::swap(rect1, rect2); // swap the POINTERS (not the content!)
		swapped = true;
	}


	if (edgesInRect12.count() == 4) {
		//  ________
		// |  ____  |
		// | |    | |
		// | |____| |
		// |________|

		// 2 is fully in 1
		return swapped ? -1 : 1;
	} if (edgesInRect12.count() == 3) {
		//  ______
		// |     _|___
		// |    | |   |
		// |    |_|___|
		// |______|
		//

		// make one rect smaller
		if (!edgesInRect12[0]) {
			rect2->x2 = rect1->x1;
		} else if (!edgesInRect12[1]) {
			rect2->x1 = rect1->x2;
		} else if (!edgesInRect12[2]) {
			rect2->z2 = rect1->z1;
		} else {
			rect2->z1 = rect1->z2;
		}
	} else if ((edgesInRect12[0] || edgesInRect12[1]) && (edgesInRect12[2] || edgesInRect12[3]) ) {
		//assert(edgesInRect12.count() == 2);

		//  ______
		// |      |
		// |  ____|___
		// |_|____|   |
		//   |________|

		// make one smaller and create a new one
		SRectangle rect3 = *rect2;

		if (edgesInRect12[2]) {
			rect2->z1 = rect1->z2;
			rect3.z2  = rect1->z2;
		} else { //(edgesInRect12[3])
			rect2->z2 = rect1->z1;
			rect3.z1  = rect1->z1;
		}

		if (edgesInRect12[0]) {
			rect3.x1 = rect1->x2;
		} else { //(edgesInRect12[1])
			rect3.x2 = rect1->x1;
		}

		// create a new one
		rectangles.push_back(rect3);
	} else if ((edgesInRect12.count() == 2) && (edgesInRect12[0] != edgesInRect21[0])) {
		//assert(edgesInRect12.count() == 2);

		//    ______
		//  _|______|_
		// | |      | |
		// |_|______|_|
		//   |______|
		//

		// make one smaller and create a new one
		SRectangle rect3 = *rect2;

		if (edgesInRect12[0]) {
			assert(edgesInRect12[0] && edgesInRect12[1] && !edgesInRect12[2] && !edgesInRect12[3]);
			rect2->z2 = rect1->z1;
			rect3.z1  = rect1->z2;
		} else {
			assert(!edgesInRect12[0] && !edgesInRect12[1] && edgesInRect12[2] && edgesInRect12[3]);
			rect2->x2 = rect1->x1;
			rect3.x1  = rect1->x2;
		}

		// create a new one
		rectangles.push_back(rect3);
	}

	return 0;
}

