bool CSMFMapFile::ReadGrassMap(void *data)
{
	ifs.Seek(sizeof(SMFHeader));

	for (int a = 0; a < header.numExtraHeaders; ++a) {
		int size = 0;
		int type = 0;

		ifs.Read(&size, 4);
		ifs.Read(&type, 4);

		swabDWordInPlace(size);
		swabDWordInPlace(type);

		if (type == MEH_Vegetation) {
			int pos = 0;
			ifs.Read(&pos, 4);
			swabDWordInPlace(pos);
			ifs.Seek(pos);
			ifs.Read(data, header.mapx / 4 * header.mapy / 4);
			/* char; no swabbing. */
			return true; //we arent interested in other extensions anyway
		}

		// assumes we can use data as scratch memory
		assert((size - 8) <= (header.mapx / 4 * header.mapy / 4));
		ifs.Read(data, size - 8);
	}

	return false;
}

TimeIndex Animation::_getTimeIndex(Real timePos) const
{
    // Uncomment following statement for work as previous
    //return timePos;

    // Build keyframe time list on demand
    if (mKeyFrameTimesDirty)
    {
        buildKeyFrameTimeList();
    }

    // Wrap time
    Real totalAnimationLength = mLength;

    if( timePos > totalAnimationLength && totalAnimationLength > 0.0f ) {
        timePos = std::fmod( timePos, totalAnimationLength );
}

    // Not best practice, but prevent from crash
    if (mKeyFrameTimes.empty()) {
        return timePos;
}

    // Search for global index
    auto it = std::lower_bound(mKeyFrameTimes.begin(), mKeyFrameTimes.end() - 1, timePos);
    return {timePos, static_cast<uint>(std::distance(mKeyFrameTimes.begin(), it))};
}

