void Serialize(ISerializer* s, void* inst) override {
	T& ct = *(T*)inst;
	if (s->IsWriting()) {
		int size = (int)ct.size();
		s->SerializeInt(&size,sizeof(int));
		for (typename T::iterator it = ct.begin(); it != ct.end(); ++it)
		{
			DeduceType<T>::Get()->Serialize(s, &*it);
		}
	} else {
		ct.clear();
		int size = 0;
		s->SerializeInt(&size, sizeof(int));
		ct.resize(size);
		for (typename T::iterator it = ct.begin(); it != ct.end(); ++it)
		{
			DeduceType<T>::Get()->Serialize(s, &*it);
		}
	}
}

bool Math::intersects(const Sphere& sphere, const AxisAlignedBox& box)
{
    if (box.isNull()) { return false;
}
    if (box.isInfinite()) { return true;
}

    // Use splitting planes
    const Vector3& center = sphere.getCenter();
    Real radius = sphere.getRadius();
    const Vector3& min = box.getMinimum();
    const Vector3& max = box.getMaximum();

    // Arvo's algorithm
    Real s;
    Real d = 0;
    for (int i = 0; i < 3; ++i)
    {
        if (center.ptr()[i] < min.ptr()[i])
        {
            s = center.ptr()[i] - min.ptr()[i];
            d += s * s; 
        }
        else if(center.ptr()[i] > max.ptr()[i])
        {
            s = center.ptr()[i] - max.ptr()[i];
            d += s * s; 
        }
    }
    return d <= radius * radius;

}

