std::string windows::GetHardwareString()
{
	std::ostringstream oss;

	unsigned char regbuf[200];
	DWORD regLength = sizeof(regbuf);
	DWORD regType = REG_SZ;
	HKEY regkey = nullptr;

	if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, R"(Hardware\Description\System\CentralProcessor\0)", 0, KEY_READ, &regkey) == ERROR_SUCCESS) {
		if (RegQueryValueEx(regkey, "ProcessorNameString", nullptr, &regType, regbuf, &regLength) == ERROR_SUCCESS) {
			oss << regbuf << "; ";
		} else {
			oss << "cannot read processor data; ";
		}

		RegCloseKey(regkey);
	} else {
		oss << "cannot open key with processor data; ";
	}

	MEMORYSTATUSEX statex;
	constexpr int div = 1024 * 1024;
	statex.dwLength = sizeof(statex);

	GlobalMemoryStatusEx(&statex);

	oss << (statex.ullTotalPhys / div) << "MB RAM, ";
	oss << (statex.ullTotalPageFile / div) << "MB pagefile";
	return oss.str();
}

