void UDPConnection::UpdateResendRequests()
{
	using P = decltype(resendRequested)::value_type;

	const auto cmpPred = [](const P& a, const P& b) { return (a.first <  b.first); };
	const auto dupPred = [](const P& a, const P& b) { return (a.first == b.first); };

	// sort by chunk-number
	std::sort(resendRequested.begin(), resendRequested.end(), cmpPred);

	{
		const auto beg = resendRequested.begin();
		const auto end = resendRequested.end();
		const auto iter = std::unique(beg, end, dupPred);

		// filter duplicates
		resendRequested.erase(iter, end);
	}

	if (erasedResendChunks.empty()) {
		return;
}

	{
		const auto pred = [&](const std::pair<std::int32_t, ChunkPtr>& p) { return (erasedResendChunks.contains(p.first)); };

		const auto beg = resendRequested.begin();
		const auto end = resendRequested.end();
		const auto pos = std::remove_if(beg, end, pred);

		// remove chunks that no longer need resending
		resendRequested.erase(pos, end);
		erasedResendChunks.clear();
	}
}

bool Technique::checkGPURules(StringStream& errors)
{
    const RenderSystemCapabilities* caps = nullptr;
    if (auto *rs = Root::getSingleton().getRenderSystem()) {
        caps = rs->getCapabilities();
}

    if (!caps && (!mGPUVendorRules.empty() || !mGPUDeviceNameRules.empty()))
    {
        errors << "GPU rules failed because the RenderSystem is NULL";
        return false;
    }

    StringStream includeRules;
    bool includeRulesPresent = false;
    bool includeRuleMatched = false;

    // Check vendors first
    for (auto& r : mGPUVendorRules)
    {
        if (r.includeOrExclude == INCLUDE)
        {
            includeRulesPresent = true;
            includeRules << Ogre::RenderSystemCapabilities::vendorToString(r.vendor) << " ";
            if (r.vendor == caps->getVendor()) {
                includeRuleMatched = true;
}
        }
        else // EXCLUDE
        {
            if (r.vendor == caps->getVendor())
            {
                errors << "Excluded GPU vendor: " << Ogre::RenderSystemCapabilities::vendorToString(r.vendor)
                    << '\n';
                return false;
            }

        }
    }

    if (includeRulesPresent && !includeRuleMatched)
    {
        errors << "Failed to match GPU vendor: " << includeRules.str( )
            << '\n';
        return false;
    }

    // now check device names
    includeRules.str(BLANKSTRING);
    includeRulesPresent = false;
    includeRuleMatched = false;

    for (auto& r : mGPUDeviceNameRules)
    {
        if (r.includeOrExclude == INCLUDE)
        {
            includeRulesPresent = true;
            includeRules << r.devicePattern << " ";
            if (StringUtil::match(caps->getDeviceName(), r.devicePattern, r.caseSensitive)) {
                includeRuleMatched = true;
}
        }
        else // EXCLUDE
        {
            if (StringUtil::match(caps->getDeviceName(), r.devicePattern, r.caseSensitive))
            {
                errors << "Excluded GPU device: " << r.devicePattern
                    << '\n';
                return false;
            }

        }
    }

    if (includeRulesPresent && !includeRuleMatched)
    {
        errors << "Failed to match GPU device: " << includeRules.str( )
            << '\n';
        return false;
    }

    // passed
    return true;
}

