void OctreePlaneBoundedVolumeListSceneQuery::execute(SceneQueryListener* listener)
{
    std::set<SceneNode*> checkedSceneNodes;

    PlaneBoundedVolumeList::iterator pi;
    PlaneBoundedVolumeList::iterator piend;
    piend = mVolumes.end();
    for (pi = mVolumes.begin(); pi != piend; ++pi)
    {
        std::list< SceneNode * > _list;
        //find the nodes that intersect the AAB
        static_cast<OctreeSceneManager*>( mParentSceneMgr ) -> findNodesIn( *pi, _list, nullptr );

        //grab all moveables from the node that intersect...
        std::list< SceneNode * >::iterator it;
        std::list< SceneNode * >::iterator itend;
        itend = _list.end();
        for (it = _list.begin(); it != itend; ++it)
        {
            // avoid double-check same scene node
            if (!checkedSceneNodes.insert(*it).second) {
                continue;
}
            for (auto *m : (*it)->getAttachedObjects())
            {
                if( (m->getQueryFlags() & mQueryMask) && 
                    (m->getTypeFlags() & mQueryTypeMask) && 
                    m->isInScene() &&
                    (*pi).intersects( m->getWorldBoundingBox() ) )
                {
                    listener -> queryResult( m );
                    // deal with attached objects, since they are not directly attached to nodes
                    if (m->getMovableType() == MOT_ENTITY)
                    {
                        auto* e = static_cast<Entity*>(m);
                        for(auto *c : e->getAttachedObjects())
                        {
                            if (c->getQueryFlags() & mQueryMask &&
                                (*pi).intersects( c->getWorldBoundingBox()))
                            {
                                listener->queryResult(c);
                            }
                        }
                    }
                }
            }
        }
    }//for
}

void CFileFilter::AddRule(const string& rule)
{
	if (rule.empty()) {
		return;
}

	// Split lines if line endings are present.
	if (rule.find('\n') != string::npos) {
		size_t beg = 0;
		size_t end = 0;
		while ((end = rule.find('\n', beg)) != string::npos) {
			//printf("line: %s\n", rule.substr(beg, end - beg).c_str());
			AddRule(rule.substr(beg, end - beg));
			beg = end + 1;
		}
		AddRule(rule.substr(beg));
		return;
	}

	// Eat leading whitespace, return if we reach end of string.
	size_t p = 0;
	while (isspace(rule[p])) {
		if (++p >= rule.length()) {
			return;
}

	// Nothing to do if the rule is a comment.
	if (rule[p] == '#') {
		return;
}

	// Eat trailing whitespace, return if we meet p.
	size_t q = rule.length() - 1;
	while (isspace(rule[q])) {
		if (--q < p) {
			return;
		}
	}

	// Build the rule.
	Rule r;
	if (rule[p] == '!') {
		r.negate = true;
		if (++p > q) {
			return;
		}
	}
	r.glob = rule.substr(p, 1 + q - p);
	r.regex = spring::regex(glob_to_regex(r.glob)
		, spring::regex::icase);
	rules.push_back(r);
	//printf("added %s%s: %s\n", r.negate ? "!" : "", r.glob.c_str(), r.regex.expression());
}

void CPlayerHandler::LoadFromSetup(const CGameSetup* setup)
{
	const std::vector<PlayerBase>& playerData = setup->GetPlayerStartingDataCont();

	const int oldSize = players.size();
	const int newSize = std::max(players.size(), playerData.size());

	assert(newSize <= MAX_PLAYERS);
	assert(players.capacity() == MAX_PLAYERS);

	for (unsigned int i = oldSize; i < newSize; ++i) {
		players.emplace_back();
	}

	for (size_t i = 0; i < playerData.size(); ++i) {
