int CPreprocessor::Token::CountNL ()
{
    if (Type == TK_EOS || Type == TK_ERROR) {
        return 0;
}

    const char *s = String;
    size_t l = Length;
    int c = 0;
    while (l > 0)
    {
        const char *n = static_cast<const char *>(memchr (s, '\n', l));
        if (!n) {
            return c;
}
        c++;
        l -= (n - s + 1);
        s = n + 1;
    }
    return c;
}

