PacketType CBaseNetProtocol::SendQuit(const std::string& reason)
{
	// NOTE:
	//   transmit size as uint16, but calculate it using uint32's so overflow is safe
	//   the extra null-terminator +1 is necessary, PackPacket adds a byte for strings
	// const uint32_t headerSize = sizeof(static_cast<uint8_t>(NETMSG_QUIT)) + sizeof(static_cast<uint16_t>(packetSize));
	const uint32_t payloadSize = reason.size() + 1;
	const uint32_t headerSize = sizeof(uint8_t) + sizeof(uint16_t);
	const uint32_t packetSize = headerSize + payloadSize;

	auto* packet = new PackPacket(packetSize, NETMSG_QUIT);
	*packet << static_cast<uint16_t>(packetSize) << reason;
	return PacketType(packet);
}

bool D3D9HardwareOcclusionQuery::pullOcclusionQuery( unsigned int* NumOfFragments ) 
{
    IDirect3DDevice9* pCurDevice = D3D9RenderSystem::getActiveD3D9Device();
    auto it     = mMapDeviceToQuery.find(pCurDevice);

    if (it == mMapDeviceToQuery.end()) {      
        return false;
}

    if (it->second == NULL) {
        return false;
}

    // in case you didn't check if query arrived and want the result now.
    if (mIsQueryResultStillOutstanding)
    {
        // Loop until the data becomes available
        DWORD pixels = 0;
        const size_t dataSize = sizeof( DWORD );
        while (1)
        {
            const HRESULT hr = it->second->GetData(reinterpret_cast<void *>(&pixels), dataSize, D3DGETDATA_FLUSH);

            if  (hr == S_FALSE) {
                continue;
}
            if  (hr == S_OK)
            {
                mPixelCount = pixels;
                *NumOfFragments = pixels;
                break;
            }
            if (hr == D3DERR_DEVICELOST)
            {
                *NumOfFragments = 0;
                SAFE_RELEASE(it->second);
                break;
            }
        } 
        mIsQueryResultStillOutstanding = false;
    }
    else
    {
        // we already stored result from last frames.
        *NumOfFragments = mPixelCount;
    }       
    return true;
}

