    : GLHardwarePixelBufferCommon(width, height, depth, parent->getFormat(), static_cast<Usage>(parent->getUsage())),
      mTarget(parent->getGLTextureTarget()), mFaceTarget(mTarget), mTextureID(parent->getGLID()),
      mLevel(level), mHwGamma(parent->isHardwareGammaEnabled()),
      mRenderSystem(renderSystem)
{
    // Get face identifier

    if(mTarget == GL_TEXTURE_CUBE_MAP) {
        mFaceTarget = GL_TEXTURE_CUBE_MAP_POSITIVE_X + face;
}

    // Get format
    mGLInternalFormat = GLPixelUtil::getGLInternalFormat(mFormat, mHwGamma);

    // Log a message
    /*
    std::stringstream str;
    str << "GLHardwarePixelBuffer constructed for texture " << mTextureID 
        << " face " << mFace << " level " << mLevel << ": "
        << "width=" << mWidth << " height="<< mHeight << " depth=" << mDepth
        << "format=" << PixelUtil::getFormatName(mFormat) << "(internal 0x"
        << std::hex << value << ")";
    LogManager::getSingleton().logMessage( 
                LML_NORMAL, str.str());
    */

    if(mWidth==0 || mHeight==0 || mDepth==0) {
        /// We are invalid, do not allocate a buffer
        return;
}
    // Allocate buffer
    //if(mUsage & HBU_STATIC)
    //  allocateBuffer();
    // Is this a render target?
    if(mUsage & TU_RENDERTARGET)
    {
        // Create render target for each slice
        mSliceTRT.reserve(mDepth);
        for(uint32 zoffset=0; zoffset<mDepth; ++zoffset)
        {
            String name = getNameForRenderTexture(parent->getName(), zoffset + face);
            GLSurfaceDesc surface;
            surface.buffer = this;
            surface.zoffset = zoffset;
            surface.numSamples = parent->getFSAA();
            RenderTexture *trt = GLRTTManager::getSingleton().createRenderTexture(name, surface, mHwGamma);
            mSliceTRT.push_back(trt);
            Root::getSingleton().getRenderSystem()->attachRenderTarget(*mSliceTRT[zoffset]);
        }
    }
}

void TextBox::filterLines()
{
    Ogre::String shown;
    unsigned int maxLines = getHeightInLines();
    auto newStart = static_cast<unsigned int>((mScrollPercentage * (mLines.size() - maxLines)) + 0.5);

    mStartingLine = newStart;

    for (unsigned int i = 0; i < maxLines; i++)
    {
        shown += mLines[mStartingLine + i] + "\n";
    }

    mTextArea->setCaption(shown);    // show just the filtered lines
}

GLenum get_tex_target(int stage)
{
    auto iter = stageToTargetMap.find(stage);
    if (iter != stageToTargetMap.end()) {
        return (*iter).second;
}
    // If no mapping set, use the current state. This will not work correctly, in general,
    // if nvparse was invoked within a display list.
    if(glIsEnabled(GL_TEXTURE_CUBE_MAP_ARB)) {
        return GL_TEXTURE_CUBE_MAP_ARB;
}
    if(glIsEnabled(GL_TEXTURE_3D)) {
        return GL_TEXTURE_3D;
}
#ifdef GL_EXT_texture_rectangle
    if(glIsEnabled(GL_TEXTURE_RECTANGLE_EXT))
        return GL_TEXTURE_RECTANGLE_EXT;
#elif defined(GL_NV_texture_rectangle)
            if(glIsEnabled(GL_TEXTURE_RECTANGLE_NV))
                    return GL_TEXTURE_RECTANGLE_NV;
#endif
    if(glIsEnabled(GL_TEXTURE_2D)) {
        return GL_TEXTURE_2D;
}
    if(glIsEnabled(GL_TEXTURE_1D)) {
        return GL_TEXTURE_1D;
}

    //otherwise make the op none...
    return GL_NONE;
}

const Matrix4& AutoParamDataSource::getTextureViewProjMatrix(size_t index) const
{
    if (index < OGRE_MAX_SIMULTANEOUS_LIGHTS && mCurrentTextureProjector[index])
    {
        if (mTextureViewProjMatrixDirty[index])
        {
            if (mCameraRelativeRendering)
            {
                // World positions are now going to be relative to the camera position
                // so we need to alter the projector view matrix to compensate
                Matrix4 viewMatrix;
                mCurrentTextureProjector[index]->calcViewMatrixRelative(
                    mCurrentCamera->getDerivedPosition(), viewMatrix);
                mTextureViewProjMatrix[index] = 
                    Matrix4::CLIPSPACE2DTOIMAGESPACE *
                    mCurrentTextureProjector[index]->getProjectionMatrixWithRSDepth() * 
                    viewMatrix;
            }
            else
            {
                mTextureViewProjMatrix[index] = 
                    Matrix4::CLIPSPACE2DTOIMAGESPACE *
                    mCurrentTextureProjector[index]->getProjectionMatrixWithRSDepth() * 
                    mCurrentTextureProjector[index]->Frustum::getViewMatrix();
            }
            mTextureViewProjMatrixDirty[index] = false;
        }
        return mTextureViewProjMatrix[index];
    }
                return Matrix4::IDENTITY;
}

void MeshLodGenerator::handleResponse(const WorkQueue::Response* res, const WorkQueue*  /*srcQ*/)
{
    auto* request = any_cast<LodWorkQueueRequest*>(res->getData());

    if(mInjectorListener){
        if(!mInjectorListener->shouldInject(request)) {
            return;
        }
    }

    request->output->inject();
    MeshLodGenerator::_configureMeshLodUsage(request->config);
    //lodConfig.mesh->buildEdgeList();

    if(mInjectorListener){
        mInjectorListener->injectionCompleted(request);
    }
}

