void ConfigHandlerImpl::Update()
{
	std::scoped_lock lck(observerMutex);

	for (const auto & changedValue : changedValues) {
		const std::string& key = changedValue.first;
		const std::string& value = changedValue.second;

		if (configsToCallbacks.contains(key)) {
			for (const NamedConfigNotifyCallback& ncnc: configsToCallbacks[key]) {
				(ncnc.callback)(key, value);
			}
		}
	}

	changedValues.clear();
}

aiInterfaceCallback_SkirmishAIs_Info_getValueByKey(
	int  /*UNUSED_interfaceId*/,
	const char* const shortName,
	const char* const version,
	const char* const key
) {
	const char* value = "";

	const SkirmishAIKey aiKey(shortName, version);

	const AILibraryManager::T_skirmishAIInfos& skirmishInfos = AILibraryManager::GetInstance()->GetSkirmishAIInfos();
	const auto inf = skirmishInfos.find(aiKey);

	if (inf == skirmishInfos.end()) {
		return value;
}

	const std::string& valueStr = (inf->second).GetInfo(key);

	if (valueStr.empty()) {
		return value;
}

	return (valueStr.c_str());
}

std::vector<std::string> CCategoryHandler::GetCategoryNames(unsigned int bits) const
{
	std::vector<std::string> names;

	names.reserve(categories.size());

	for (unsigned int bit = 1; bit != 0; bit = (bit << 1)) {
		if ((bit & bits) == 0) {
			continue;
}

		for (const auto & categorie : categories) {
			if (categorie.second != bit) {
				continue;
}

			names.push_back(categorie.first);
		}
	}

	return names;
}

