template<class... Args>
std::string format(const char* fmt, const Args&... args) {
	char buff[4096];
	const int len = SNPRINTF(buff, 4096, fmt, args...);
	if ((len > 0) && (len < 4096)) {
		return std::string(buff, len);
}

	return {};
}

