static void
yy_stack_print (yytype_int16 *yybottom, const yytype_int16 *yytop)
{
  YYFPRINTF (stderr, "Stack now");
  for (; yybottom <= yytop; yybottom++)
    {
      int yybot = *yybottom;
      YYFPRINTF (stderr, " %d", yybot);
    }
  YYFPRINTF (stderr, "\n");
}

inline float isqrt2_nosse(float x) {
	float xh = 0.5f * x;
	std::int32_t i = *reinterpret_cast<std::int32_t*>(&x);
	// "magic number" which makes a very good first guess
	i = 0x5f375a86 - (i >> 1);
	x = *reinterpret_cast<float*>(&i);
	// Newton's method. Two iterations for more accuracy but less speed.
	x = x * (1.5f - (xh * (x * x)));
	x = x * (1.5f - (xh * (x * x)));
	return x;

}

